# ================= step 3: reverse phonetic =================
phonetic_map = {
    "A":"ALPHA","B":"BRAVO","C":"CHARLIE","D":"DELTA","E":"ECHO","F":"FOXTROT",
    "G":"GOLF","H":"HOTEL","I":"INDIA","J":"JULIETT","K":"KILO","L":"LIMA",
    "M":"MIKE","N":"NOVEMBER","O":"OSCAR","P":"PAPA","Q":"QUEBEC","R":"ROMEO",
    "S":"SIERRA","T":"TANGO","U":"UNIFORM","V":"VICTOR","W":"WHISKEY","X":"XRAY",
    "Y":"YANKEE","Z":"ZULU","_":"UNDERSCORE","{":"OPENCURLYBRACE","}":"CLOSECURLYBRACE",
    "0":"ZERO","1":"ONE","2":"TWO","3":"THREE","4":"FOUR","5":"FIVE","6":"SIX",
    "7":"SEVEN","8":"EIGHT","9":"NINE"
}

rev = {v: k for k, v in phonetic_map.items()}

def reverse_phonetic(s):
    out = ""
    i = 0
    while i < len(s):
        for w, c in rev.items():
            if s.startswith(w, i):
                out += c
                i += len(w)
                break
        else:
            i += 1
    return out

# ================= step 4: reverse twice =================
lvl1 = reverse_phonetic(pt)
lvl2 = reverse_phonetic(lvl1)

print("[+] After 1st reverse phonetic:")
print(lvl1[:200], "\n")

print("[+] Recovered flag (or almost):")
print(lvl2)